   1: // ============================================================
   2: // Core Tools — Read, Write, Edit, Bash, Glob, Grep
   3: // ============================================================
   4: 
   5: import * as fs from "node:fs";
   6: import * as path from "node:path";
   7: import { exec, execSync } from "node:child_process";
   8: import { promisify } from "node:util";
   9: import fg from "fast-glob";
  10: import type { Tool, ToolContext, ToolResult } from "./types.js";
  11: import { createTool } from "./tool-registry.js";
  12: import {
  13:   checkDangerousPattern,
  14:   isBlockedPath,
  15: } from "./permissions.js";
  16: import { TodoTool } from "./todo-tool.js";
  17: import { WebFetchTool } from "./web-fetch.js";
  18: import { WebSearchTool } from "./web-search.js";
  19: import { TaskTool } from "./task-tool.js";
  20: import {
  21:   markRead,
  22:   checkReadBeforeEdit,
  23:   refreshRead,
  24: } from "./read-tracker.js";
  25: 
  26: const execAsync = promisify(exec);
  27: 
  28: // --- Input type definitions for each tool ---
  29: 
  30: interface ReadInput {
  31:   filePath: string;
  32:   offset?: number;
  33:   limit?: number;
  34:   [key: string]: unknown;
  35: }
  36: 
  37: interface WriteInput {
  38:   filePath: string;
  39:   content: string;
  40:   [key: string]: unknown;
  41: }
  42: 
  43: interface EditInput {
  44:   filePath: string;
  45:   old_string: string;
  46:   new_string: string;
  47:   replace_all?: boolean;
  48:   [key: string]: unknown;
  49: }
  50: 
  51: interface BashInput {
  52:   command: string;
  53:   description: string;
  54:   timeout?: number;
  55:   [key: string]: unknown;
  56: }
  57: 
  58: interface GlobInput {
  59:   pattern: string;
  60:   path?: string;
  61:   [key: string]: unknown;
  62: }
  63: 
  64: interface GrepInput {
  65:   pattern: string;
  66:   path?: string;
  67:   include?: string;
  68:   [key: string]: unknown;
  69: }
  70: 
  71: // ============================================================
  72: // Read Tool
  73: // ============================================================
  74: 
  75: export const ReadTool: Tool = createTool<ReadInput>({
  76:   name: "read",
  77:   description: "Read a file from the local filesystem",
  78:   promptDescription:
  79:     "Read a file from the local filesystem. Returns text content with line numbers. " +
  80:     "Images (PNG/JPG/GIF/WebP) and PDFs are returned as visual content blocks you can see directly.",
  81:   inputSchema: {
  82:     type: "object",
  83:     properties: {
  84:       filePath: {
  85:         type: "string",
  86:         description: "The absolute path to the file to read",
  87:       },
  88:       offset: {
  89:         type: "number",
  90:         description: "Line number to start reading from (1-based)",
  91:       },
  92:       limit: {
  93:         type: "number",
  94:         description: "Maximum number of lines to read",
  95:       },
  96:     },
  97:     required: ["filePath"],
  98:   },
  99:   isReadOnly: true,
 100:   isConcurrencySafe: true,
 101: 
 102:   async call(input, context): Promise<ToolResult> {
 103:     const resolution = resolveInWorkspace(input.filePath, context.workspaceRoot);
 104:     if (!resolution.ok) {
 105:       return { content: "", error: resolution.error };
 106:     }
 107:     const filePath = resolution.path;
 108: 
 109:     if (isBlockedPath(filePath)) {
 110:       return {
 111:         content: "",
 112:         error: `Access denied: "${input.filePath}" is a blocked path`,
 113:       };
 114:     }
 115: 
 116:     try {
 117:       const stat = fs.statSync(filePath);
 118: 
 119:       if (stat.isDirectory()) {
 120:         return {
 121:           content: "",
 122:           error: `"${input.filePath}" is a directory, not a file`,
 123:         };
 124:       }
 125: 
 126:       // Check for binary files
 127:       const buffer = fs.readFileSync(filePath);
 128: 
 129:       // Images and PDFs return as multimodal content blocks.
 130:       const mediaType = imageMediaType(filePath);
 131:       if (mediaType) {
 132:         if (stat.size > MAX_IMAGE_BYTES) {
 133:           return {
 134:             content: `[Image too large to load: ${input.filePath} (${stat.size} bytes, max ${MAX_IMAGE_BYTES})]`,
 135:             metadata: { fileSize: stat.size },
 136:           };
 137:         }
 138:         markRead(context.sessionId, filePath, stat.mtimeMs);
 139:         return {
 140:           content: `[Loaded ${mediaType}: ${input.filePath}]`,
 141:           metadata: { fileSize: stat.size },
 142:           images: [
 143:             {
 144:               type: "image",
 145:               source: {
 146:                 type: "base64",
 147:                 media_type: mediaType,
 148:                 data: buffer.toString("base64"),
 149:               },
 150:             },
 151:           ],
 152:         };
 153:       }
 154: 
 155:       if (isBinary(buffer)) {
 156:         markRead(context.sessionId, filePath, stat.mtimeMs);
 157:         return {
 158:           content: `[Binary file: ${filePath}]`,
 159:           metadata: { fileSize: stat.size },
 160:         };
 161:       }
 162: 
 163:       let lines = buffer.toString("utf-8").split("\n");
 164:       const totalLines = lines.length;
 165: 
 166:       // Apply offset and limit
 167:       const start = (input.offset ?? 1) - 1;
 168:       const end = input.limit ? start + input.limit : Math.min(start + 2000, totalLines);
 169:       lines = lines.slice(start, end);
 170: 
 171:       // Add line numbers (4-space padded)
 172:       const numbered = lines
 173:         .map((line, i) => {
 174:           const num = String(start + i + 1).padStart(4, " ");
 175:           return `${num}: ${line}`;
 176:         })
 177:         .join("\n");
 178: 
 179:       const truncated = end < totalLines;
 180: 
 181:       markRead(context.sessionId, filePath, stat.mtimeMs);
 182: 
 183:       return {
 184:         content: numbered,
 185:         truncated,
 186:         metadata: {
 187:           linesRead: lines.length,
 188:           fileSize: stat.size,
 189:         },
 190:       };
 191:     } catch (error: any) {
 192:       if (error.code === "ENOENT") {
 193:         return { content: "", error: `File not found: "${input.filePath}"` };
 194:       }
 195:       return {
 196:         content: "",
 197:         error: `Error reading file: ${error.message}`,
 198:       };
 199:     }
 200:   },
 201: 
 202:   async checkPermissions(_input, _context) {
 203:     return { allowed: true }; // Read-only, always allowed
 204:   },
 205: });
 206: 
 207: // ============================================================
 208: // Write Tool
 209: // ============================================================
 210: 
 211: export const WriteTool: Tool = createTool<WriteInput>({
 212:   name: "write",
 213:   description: "Create or overwrite a file",
 214:   promptDescription:
 215:     "Create or overwrite a file. Creates parent directories automatically.",
 216:   inputSchema: {
 217:     type: "object",
 218:     properties: {
 219:       filePath: {
 220:         type: "string",
 221:         description: "The absolute path where to write the file",
 222:       },
 223:       content: {
 224:         type: "string",
 225:         description: "Content to write to the file",
 226:       },
 227:     },
 228:     required: ["filePath", "content"],
 229:   },
 230:   isReadOnly: false,
 231:   isConcurrencySafe: false, // Same file writes must be serial
 232: 
 233:   async call(input, context): Promise<ToolResult> {
 234:     const resolution = resolveInWorkspace(input.filePath, context.workspaceRoot);
 235:     if (!resolution.ok) {
 236:       return { content: "", error: resolution.error };
 237:     }
 238:     const filePath = resolution.path;
 239: 
 240:     if (isBlockedPath(filePath)) {
 241:       return {
 242:         content: "",
 243:         error: `Access denied: "${input.filePath}" is a blocked path`,
 244:       };
 245:     }
 246: 
 247:     try {
 248:       // Create parent directories
 249:       const dir = path.dirname(filePath);
 250:       fs.mkdirSync(dir, { recursive: true });
 251: 
 252:       const existed = fs.existsSync(filePath);
 253:       fs.writeFileSync(filePath, input.content, "utf-8");
 254: 
 255:       const size = Buffer.byteLength(input.content, "utf-8");
 256:       const action = existed ? "Updated" : "Created";
 257: 
 258:       return {
 259:         content: `${action} file: ${input.filePath} (${formatSize(size)})`,
 260:         metadata: { fileSize: size },
 261:       };
 262:     } catch (error: any) {
 263:       return {
 264:         content: "",
 265:         error: `Error writing file: ${error.message}`,
 266:       };
 267:     }
 268:   },
 269: 
 270:   async checkPermissions(input, context) {
 271:     const danger = checkDangerousPattern(
 272:       "write",
 273:       input,
 274:       context.workspaceRoot,
 275:     );
 276:     if (danger.dangerous) {
 277:       return { allowed: false, reason: danger.reason! };
 278:     }
 279:     return { allowed: true };
 280:   },
 281: });
 282: 
 283: // ============================================================
 284: // Edit Tool (Search/Replace — the most critical tool!)
 285: // ============================================================
 286: 
 287: export const EditTool: Tool = createTool<EditInput>({
 288:   name: "edit",
 289:   description: "Make precise edits using search/replace",
 290:   promptDescription:
 291:     "Make precise edits using search/replace. old_string must match exactly including whitespace and indentation. If not unique, add more surrounding context lines.",
 292:   inputSchema: {
 293:     type: "object",
 294:     properties: {
 295:       filePath: {
 296:         type: "string",
 297:         description: "The absolute path to the file to edit",
 298:       },
 299:       old_string: {
 300:         type: "string",
 301:         description:
 302:           "The text to replace. Must match EXACTLY including whitespace and indentation. If not unique, add more surrounding context lines.",
 303:       },
 304:       new_string: {
 305:         type: "string",
 306:         description:
 307:           "The text to replace it with. Use empty string to delete.",
 308:       },
 309:       replace_all: {
 310:         type: "boolean",
 311:         description:
 312:           "Replace every occurrence of old_string instead of requiring a unique match. Defaults to false.",
 313:       },
 314:     },
 315:     required: ["filePath", "old_string", "new_string"],
 316:   },
 317:   isReadOnly: false,
 318:   isConcurrencySafe: false, // Same file edits must be serial
 319: 
 320:   async call(input, context): Promise<ToolResult> {
 321:     const resolution = resolveInWorkspace(input.filePath, context.workspaceRoot);
 322:     if (!resolution.ok) {
 323:       return { content: "", error: resolution.error };
 324:     }
 325:     const filePath = resolution.path;
 326: 
 327:     if (isBlockedPath(filePath)) {
 328:       return {
 329:         content: "",
 330:         error: `Access denied: "${input.filePath}" is a blocked path`,
 331:       };
 332:     }
 333: 
 334:     try {
 335:       const statBefore = statMtimeMs(filePath);
 336:       const gate = checkReadBeforeEdit(context.sessionId, filePath, statBefore);
 337:       if (!gate.ok) {
 338:         return { content: "", error: gate.reason! };
 339:       }
 340: 
 341:       const content = fs.readFileSync(filePath, "utf-8");
 342:       const oldStr = input.old_string;
 343:       const newStr = input.new_string;
 344:       const replaceAll = input.replace_all === true;
 345: 
 346:       // Count occurrences
 347:       let count = 0;
 348:       let pos = 0;
 349:       while ((pos = content.indexOf(oldStr, pos)) !== -1) {
 350:         count++;
 351:         pos += oldStr.length;
 352:       }
 353: 
 354:       if (count === 0) {
 355:         return {
 356:           content: "",
 357:           error:
 358:             `old_string not found in file. Tip: re-read the file to ensure ` +
 359:             `exact whitespace and indentation match.`,
 360:         };
 361:       }
 362: 
 363:       if (count > 1 && !replaceAll) {
 364:         return {
 365:           content: "",
 366:           error:
 367:             `Found ${count} matches for old_string. Provide more surrounding ` +
 368:             `context lines to make the match unique, or set replace_all: true.`,
 369:         };
 370:       }
 371: 
 372:       // Replace via index-based splicing instead of String.replace, which
 373:       // would interpret special patterns ($&, $1, $`, $') in new_string and
 374:       // silently corrupt the content.
 375:       let newContent: string;
 376:       if (replaceAll) {
 377:         newContent = spliceAll(content, oldStr, newStr);
 378:       } else {
 379:         const idx = content.indexOf(oldStr);
 380:         newContent =
 381:           content.slice(0, idx) + newStr + content.slice(idx + oldStr.length);
 382:       }
 383:       fs.writeFileSync(filePath, newContent, "utf-8");
 384: 
 385:       // Keep the read tracker current so chained edits don't trip the gate.
 386:       const after = statMtimeMs(filePath);
 387:       if (after !== undefined) refreshRead(context.sessionId, filePath, after);
 388: 
 389:       // Generate a simple diff
 390:       const diff = generateSimpleDiff(oldStr, newStr);
 391:       const summary = replaceAll
 392:         ? `Edit applied to ${input.filePath} (${count} occurrence${count > 1 ? "s" : ""}):`
 393:         : `Edit applied to ${input.filePath}:`;
 394:       return {
 395:         content: `${summary}\n${diff}`,
 396:         metadata: { fileSize: Buffer.byteLength(newContent, "utf-8") },
 397:       };
 398:     } catch (error: any) {
 399:       if (error.code === "ENOENT") {
 400:         return { content: "", error: `File not found: "${input.filePath}"` };
 401:       }
 402:       return {
 403:         content: "",
 404:         error: `Error editing file: ${error.message}`,
 405:       };
 406:     }
 407:   },
 408: 
 409:   async checkPermissions(input, context) {
 410:     const danger = checkDangerousPattern(
 411:       "edit",
 412:       input,
 413:       context.workspaceRoot,
 414:     );
 415:     if (danger.dangerous) {
 416:       return { allowed: false, reason: danger.reason! };
 417:     }
 418:     return { allowed: true };
 419:   },
 420: });
 421: 
 422: // ============================================================
 423: // MultiEdit Tool — atomic batch edits on a single file
 424: // ============================================================
 425: 
 426: interface MultiEditOp {
 427:   old_string: string;
 428:   new_string: string;
 429:   replace_all?: boolean;
 430: }
 431: 
 432: interface MultiEditInput {
 433:   filePath: string;
 434:   edits: MultiEditOp[];
 435:   [key: string]: unknown;
 436: }
 437: 
 438: export const MultiEditTool: Tool = createTool<MultiEditInput>({
 439:   name: "multi_edit",
 440:   description: "Apply multiple search/replace edits to a single file atomically",
 441:   promptDescription:
 442:     "Apply multiple search/replace edits to ONE file in a single atomic operation. " +
 443:     "Provide filePath and edits (an array of {old_string, new_string, replace_all?}). " +
 444:     "Edits apply in order, each to the result of the previous one. " +
 445:     "If ANY edit fails (no match, or a non-unique match without replace_all), " +
 446:     "NOTHING is written — the file is left untouched. Prefer this over multiple " +
 447:     "edit calls when changing several places in the same file.",
 448:   inputSchema: {
 449:     type: "object",
 450:     properties: {
 451:       filePath: {
 452:         type: "string",
 453:         description: "The absolute path to the file to edit",
 454:       },
 455:       edits: {
 456:         type: "array",
 457:         description:
 458:           "Ordered list of edits. Each is {old_string, new_string, replace_all?}. " +
 459:           "Applied sequentially; all must succeed or none are written.",
 460:         items: {
 461:           type: "object",
 462:           properties: {
 463:             old_string: { type: "string", description: "Text to find (exact match)" },
 464:             new_string: { type: "string", description: "Replacement text" },
 465:             replace_all: {
 466:               type: "boolean",
 467:               description: "Replace all occurrences of this edit's old_string",
 468:             },
 469:           },
 470:           required: ["old_string", "new_string"],
 471:         },
 472:       },
 473:     },
 474:     required: ["filePath", "edits"],
 475:   },
 476:   isReadOnly: false,
 477:   isConcurrencySafe: false, // Same file — must be serial
 478: 
 479:   async call(input, context): Promise<ToolResult> {
 480:     const resolution = resolveInWorkspace(input.filePath, context.workspaceRoot);
 481:     if (!resolution.ok) {
 482:       return { content: "", error: resolution.error };
 483:     }
 484:     const filePath = resolution.path;
 485: 
 486:     if (isBlockedPath(filePath)) {
 487:       return {
 488:         content: "",
 489:         error: `Access denied: "${input.filePath}" is a blocked path`,
 490:       };
 491:     }
 492: 
 493:     if (!Array.isArray(input.edits) || input.edits.length === 0) {
 494:       return { content: "", error: "edits must be a non-empty array" };
 495:     }
 496: 
 497:     try {
 498:       const statBefore = statMtimeMs(filePath);
 499:       const gate = checkReadBeforeEdit(context.sessionId, filePath, statBefore);
 500:       if (!gate.ok) {
 501:         return { content: "", error: gate.reason! };
 502:       }
 503: 
 504:       const original = fs.readFileSync(filePath, "utf-8");
 505:       let working = original;
 506: 
 507:       // Apply edits in memory; bail out before writing if any fails.
 508:       for (let i = 0; i < input.edits.length; i++) {
 509:         const { old_string: oldStr, new_string: newStr, replace_all } =
 510:           input.edits[i];
 511: 
 512:         if (typeof oldStr !== "string" || typeof newStr !== "string") {
 513:           return {
 514:             content: "",
 515:             error: `Edit #${i + 1}: old_string and new_string are required.`,
 516:           };
 517:         }
 518: 
 519:         let count = 0;
 520:         let pos = 0;
 521:         while ((pos = working.indexOf(oldStr, pos)) !== -1) {
 522:           count++;
 523:           pos += oldStr.length || 1;
 524:         }
 525: 
 526:         if (count === 0) {
 527:           return {
 528:             content: "",
 529:             error:
 530:               `Edit #${i + 1}: old_string not found (after previous edits applied). ` +
 531:               `No changes were written.`,
 532:           };
 533:         }
 534:         if (count > 1 && replace_all !== true) {
 535:           return {
 536:             content: "",
 537:             error:
 538:               `Edit #${i + 1}: found ${count} matches. Add context to make it unique, ` +
 539:               `or set replace_all: true. No changes were written.`,
 540:           };
 541:         }
 542: 
 543:         if (replace_all === true) {
 544:           working = spliceAll(working, oldStr, newStr);
 545:         } else {
 546:           const idx = working.indexOf(oldStr);
 547:           working =
 548:             working.slice(0, idx) + newStr + working.slice(idx + oldStr.length);
 549:         }
 550:       }
 551: 
 552:       // All edits succeeded — commit once.
 553:       fs.writeFileSync(filePath, working, "utf-8");
 554: 
 555:       const after = statMtimeMs(filePath);
 556:       if (after !== undefined) refreshRead(context.sessionId, filePath, after);
 557: 
 558:       return {
 559:         content: `Applied ${input.edits.length} edits to ${input.filePath} atomically.`,
 560:         metadata: { fileSize: Buffer.byteLength(working, "utf-8") },
 561:       };
 562:     } catch (error: any) {
 563:       if (error.code === "ENOENT") {
 564:         return { content: "", error: `File not found: "${input.filePath}"` };
 565:       }
 566:       return { content: "", error: `Error editing file: ${error.message}` };
 567:     }
 568:   },
 569: 
 570:   async checkPermissions(input, context) {
 571:     const danger = checkDangerousPattern("edit", input, context.workspaceRoot);
 572:     if (danger.dangerous) {
 573:       return { allowed: false, reason: danger.reason! };
 574:     }
 575:     return { allowed: true };
 576:   },
 577: });
 578: 
 579: // ============================================================
 580: // Bash Tool
 581: // ============================================================
 582: 
 583: export const BashTool: Tool = createTool<BashInput>({
 584:   name: "bash",
 585:   description: "Execute a shell command",
 586:   promptDescription:
 587:     "Execute a shell command. Commands must be non-interactive. Output truncated at 30k characters.",
 588:   inputSchema: {
 589:     type: "object",
 590:     properties: {
 591:       command: {
 592:         type: "string",
 593:         description: "The CLI command to execute",
 594:       },
 595:       description: {
 596:         type: "string",
 597:         description: "What this command does (shown to user)",
 598:       },
 599:       timeout: {
 600:         type: "number",
 601:         description: "Timeout in ms (default: 120000)",
 602:       },
 603:     },
 604:     required: ["command", "description"],
 605:   },
 606:   isReadOnly: false,
 607:   isConcurrencySafe: true,
 608: 
 609:   async call(input, context): Promise<ToolResult> {
 610:     const timeout = input.timeout ?? 120_000;
 611: 
 612:     try {
 613:       const { stdout, stderr } = await execAsync(input.command, {
 614:         cwd: context.workspaceRoot,
 615:         timeout,
 616:         maxBuffer: 10 * 1024 * 1024, // 10MB
 617:         shell: process.env.ComSpec || (process.platform === "win32" ? "cmd.exe" : "/bin/bash"),
 618:       });
 619: 
 620:       let output = "";
 621:       if (stdout) output += stdout;
 622:       if (stderr) output += (output ? "\n" : "") + stderr;
 623: 
 624:       const truncated = output.length > 30_000;
 625:       if (truncated) {
 626:         output = output.slice(0, 30_000) + "\n[... result too long, truncated]";
 627:       }
 628: 
 629:       return {
 630:         content: output || "(no output)",
 631:         truncated,
 632:         metadata: { exitCode: 0 },
 633:       };
 634:     } catch (error: any) {
 635:       let output = "";
 636:       if (error.stdout) output += error.stdout;
 637:       if (error.stderr) output += (output ? "\n" : "") + error.stderr;
 638: 
 639:       const truncated = output.length > 30_000;
 640:       if (truncated) {
 641:         output = output.slice(0, 30_000) + "\n[... result too long, truncated]";
 642:       }
 643: 
 644:       return {
 645:         content: output || error.message,
 646:         truncated,
 647:         metadata: { exitCode: error.code || 1 },
 648:       };
 649:     }
 650:   },
 651: 
 652:   async checkPermissions(input, context) {
 653:     const danger = checkDangerousPattern(
 654:       "bash",
 655:       input,
 656:       context.workspaceRoot,
 657:     );
 658:     if (danger.dangerous) {
 659:       return { allowed: false, reason: danger.reason! };
 660:     }
 661:     return { allowed: true };
 662:   },
 663: });
 664: 
 665: // ============================================================
 666: // Glob Tool
 667: // ============================================================
 668: 
 669: export const GlobTool: Tool = createTool<GlobInput>({
 670:   name: "glob",
 671:   description: "Find files matching a glob pattern",
 672:   promptDescription:
 673:     'Find files matching a glob pattern. Example patterns: "**/*.ts", "src/**/*.test.ts"',
 674:   inputSchema: {
 675:     type: "object",
 676:     properties: {
 677:       pattern: {
 678:         type: "string",
 679:         description: "Glob pattern, e.g. '**/*.ts' or 'src/**/*.test.ts'",
 680:       },
 681:       path: {
 682:         type: "string",
 683:         description: "Directory to search in (default: workspace root)",
 684:       },
 685:     },
 686:     required: ["pattern"],
 687:   },
 688:   isReadOnly: true,
 689:   isConcurrencySafe: true,
 690: 
 691:   async call(input, context): Promise<ToolResult> {
 692:     const searchDir = input.path
 693:       ? path.resolve(context.workspaceRoot, input.path)
 694:       : context.workspaceRoot;
 695: 
 696:     try {
 697:       const files = await fg(input.pattern, {
 698:         cwd: searchDir,
 699:         ignore: ["**/node_modules/**", "**/.git/**"],
 700:         absolute: false,
 701:         dot: false,
 702:       });
 703: 
 704:       const MAX_RESULTS = 500;
 705:       const truncated = files.length > MAX_RESULTS;
 706:       const resultFiles = files.slice(0, MAX_RESULTS);
 707:       // Sort for deterministic output
 708:       resultFiles.sort();
 709: 
 710:       const content =
 711:         resultFiles.length === 0
 712:           ? "No files found matching pattern."
 713:           : resultFiles.join("\n");
 714: 
 715:       return {
 716:         content,
 717:         truncated,
 718:         metadata: { linesRead: resultFiles.length },
 719:       };
 720:     } catch (error: any) {
 721:       return {
 722:         content: "",
 723:         error: `Error searching files: ${error.message}`,
 724:       };
 725:     }
 726:   },
 727: 
 728:   async checkPermissions(_input, _context) {
 729:     return { allowed: true }; // Read-only
 730:   },
 731: });
