 737: export const GrepTool: Tool = createTool<GrepInput>({
 738:   name: "grep",
 739:   description: "Search file contents with regex",
 740:   promptDescription:
 741:     "Search file contents with regex pattern. Uses ripgrep if available, falls back to Node.js.",
 742:   inputSchema: {
 743:     type: "object",
 744:     properties: {
 745:       pattern: {
 746:         type: "string",
 747:         description: "Regex pattern to search for",
 748:       },
 749:       path: {
 750:         type: "string",
 751:         description: "Directory or file to search (default: workspace root)",
 752:       },
 753:       include: {
 754:         type: "string",
 755:         description: "File pattern filter, e.g. '*.ts'",
 756:       },
 757:     },
 758:     required: ["pattern"],
 759:   },
 760:   isReadOnly: true,
 761:   isConcurrencySafe: true,
 762: 
 763:   async call(input, context): Promise<ToolResult> {
 764:     const searchDir = input.path
 765:       ? path.resolve(context.workspaceRoot, input.path)
 766:       : context.workspaceRoot;
 767: 
 768:     // Try ripgrep first, fall back to Node.js
 769:     try {
 770:       let cmd = `rg --line-number --no-heading --color never `;
 771: 
 772:       if (input.include) {
 773:         cmd += `--glob '${input.include}' `;
 774:       }
 775: 
 776:       // Ignore common directories
 777:       cmd += `--glob '!node_modules' --glob '!.git' `;
 778: 
 779:       // Escape the pattern for shell
 780:       const escaped = input.pattern.replace(/'/g, "'\\''");
 781:       cmd += `'${escaped}' '${searchDir}'`;
 782: 
 783:       const { stdout } = await execAsync(cmd, {
 784:         timeout: 30_000,
 785:         maxBuffer: 10 * 1024 * 1024,
 786:       });
 787: 
 788:       const lines = stdout.trim().split("\n").filter(Boolean);
 789:       const MAX_RESULTS = 250;
 790:       const truncated = lines.length > MAX_RESULTS;
 791: 
 792:       if (lines.length === 0) {
 793:         return { content: "No matches found." };
 794:       }
 795: 
 796:       return {
 797:         content: lines.slice(0, MAX_RESULTS).join("\n"),
 798:         truncated,
 799:         metadata: { linesRead: Math.min(lines.length, MAX_RESULTS) },
 800:       };
 801:     } catch (error: any) {
 802:       // rg not found or error — fall back
 803:       if (error.code === 1 && error.stdout === "") {
 804:         return { content: "No matches found." };
 805:       }
 806: 
 807:       try {
 808:         // Fallback: use fast-glob + manual regex search
 809:         const pattern = input.include || "**/*";
 810:         const files = await fg(pattern, {
 811:           cwd: searchDir,
 812:           ignore: ["**/node_modules/**", "**/.git/**"],
 813:           absolute: true,
 814:         });
 815: 
 816:         const results: string[] = [];
 817:         const regex = new RegExp(input.pattern, "gi");
 818: 
 819:         for (const file of files.slice(0, 100)) {
 820:           try {
 821:             const stat = fs.statSync(file);
 822:             if (stat.isDirectory() || stat.size > 1024 * 1024) continue;
 823: 
 824:             const content = fs.readFileSync(file, "utf-8");
 825:             const lines = content.split("\n");
 826:             for (let i = 0; i < lines.length; i++) {
 827:               if (regex.test(lines[i])) {
 828:                 const relPath = path.relative(context.workspaceRoot, file);
 829:                 results.push(`${relPath}:${i + 1}: ${lines[i].trim()}`);
 830:                 regex.lastIndex = 0; // Reset
 831:               }
 832:             }
 833:           } catch {
 834:             // Skip unreadable files
 835:           }
 836:         }
 837: 
 838:         const MAX_RESULTS = 250;
 839:         const truncated = results.length > MAX_RESULTS;
 840: 
 841:         if (results.length === 0) {
 842:           return { content: "No matches found." };
 843:         }
 844: 
 845:         return {
 846:           content: results.slice(0, MAX_RESULTS).join("\n"),
 847:           truncated,
 848:           metadata: { linesRead: Math.min(results.length, MAX_RESULTS) },
 849:         };
 850:       } catch (fallbackError: any) {
 851:         return {
 852:           content: "",
 853:           error: `Error searching: ${fallbackError.message}`,
 854:         };
 855:       }
 856:     }
 857:   },
 858: 
 859:   async checkPermissions(_input, _context) {
 860:     return { allowed: true }; // Read-only
 861:   },
 862: });
